{
  "root": "root_stack",
  "state": {},
  "elements": {
    "root_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title_stack",
        "description_text",
        "main_image",
        "divider_1",
        "ingredients_prep_stack",
        "divider_2",
        "baking_tips_stack"
      ]
    },
    "title_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "title_text",
        "title_icon"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Classic Soft & Chewy Chocolate Chip Cookies",
        "variant": "h3"
      },
      "children": []
    },
    "title_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000017_01_2_star.svg"
      },
      "children": []
    },
    "description_text": {
      "type": "Text",
      "props": {
        "text": "This simple, no-chill recipe delivers perfectly soft and chewy chocolate chip cookies every time. Using both brown and white sugar ensures a crisp edge with a wonderfully moist center, ready to enjoy in under 30 minutes."
      },
      "children": []
    },
    "main_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000017_01_1_Chocolate_Chip_Cookies_-_kimberlykv.jpg"
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "ingredients_prep_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "ingredients_prep_title",
        "ingredients_stack",
        "instructions_stack"
      ]
    },
    "ingredients_prep_title": {
      "type": "Text",
      "props": {
        "text": "Ingredients & Preparation",
        "variant": "h3"
      },
      "children": []
    },
    "ingredients_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ingredients_title",
        "ing_1",
        "ing_2",
        "ing_3",
        "ing_4",
        "ing_5",
        "ing_6",
        "ing_7",
        "ing_8",
        "ing_9"
      ]
    },
    "ingredients_title": {
      "type": "Text",
      "props": {
        "text": "Ingredients",
        "variant": "label"
      },
      "children": []
    },
    "ing_1": {
      "type": "Text",
      "props": {
        "text": "• 2 ¼ cups all-purpose flour"
      },
      "children": []
    },
    "ing_2": {
      "type": "Text",
      "props": {
        "text": "• 1 teaspoon baking soda"
      },
      "children": []
    },
    "ing_3": {
      "type": "Text",
      "props": {
        "text": "• ½ teaspoon salt"
      },
      "children": []
    },
    "ing_4": {
      "type": "Text",
      "props": {
        "text": "• 1 cup (2 sticks) unsalted butter, softened"
      },
      "children": []
    },
    "ing_5": {
      "type": "Text",
      "props": {
        "text": "• ¾ cup granulated sugar"
      },
      "children": []
    },
    "ing_6": {
      "type": "Text",
      "props": {
        "text": "• ¾ cup packed light brown sugar"
      },
      "children": []
    },
    "ing_7": {
      "type": "Text",
      "props": {
        "text": "• 2 large eggs, room temperature"
      },
      "children": []
    },
    "ing_8": {
      "type": "Text",
      "props": {
        "text": "• 1 teaspoon vanilla extract"
      },
      "children": []
    },
    "ing_9": {
      "type": "Text",
      "props": {
        "text": "• 2 cups semi-sweet chocolate chips"
      },
      "children": []
    },
    "instructions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instructions_title",
        "inst_1",
        "inst_2",
        "inst_3",
        "inst_4",
        "inst_5",
        "inst_6",
        "inst_7",
        "inst_8",
        "inst_9"
      ]
    },
    "instructions_title": {
      "type": "Text",
      "props": {
        "text": "Instructions",
        "variant": "label"
      },
      "children": []
    },
    "inst_1": {
      "type": "Text",
      "props": {
        "text": "1. Preheat & Prep: Preheat your oven to 375°F (190°C). Line two large baking sheets with parchment paper."
      },
      "children": []
    },
    "inst_2": {
      "type": "Text",
      "props": {
        "text": "2. Combine Dry Ingredients: In a medium bowl, whisk together the all-purpose flour, baking soda, and salt. Set aside."
      },
      "children": []
    },
    "inst_3": {
      "type": "Text",
      "props": {
        "text": "3. Cream Butter & Sugars: In a large bowl using an electric mixer, beat the softened butter, granulated sugar, and brown sugar on medium speed until the mixture is light and fluffy, about 2-3 minutes."
      },
      "children": []
    },
    "inst_4": {
      "type": "Text",
      "props": {
        "text": "4. Add Wet Ingredients: Beat in the eggs one at a time, mixing well after each addition. Stir in the vanilla extract."
      },
      "children": []
    },
    "inst_5": {
      "type": "Text",
      "props": {
        "text": "5. Combine Wet & Dry: Gradually add the flour mixture to the wet ingredients, mixing on low speed until just combined. Be careful not to overmix the dough."
      },
      "children": []
    },
    "inst_6": {
      "type": "Text",
      "props": {
        "text": "6. Add Chocolate: Using a spatula or wooden spoon, gently stir in the semi-sweet chocolate chips until they are evenly distributed."
      },
      "children": []
    },
    "inst_7": {
      "type": "Text",
      "props": {
        "text": "7. Portion Dough: Drop rounded tablespoons of dough about 2 inches apart onto the prepared baking sheets."
      },
      "children": []
    },
    "inst_8": {
      "type": "Text",
      "props": {
        "text": "8. Bake: Bake for 9-11 minutes, or until the edges are golden brown and the centers are set."
      },
      "children": []
    },
    "inst_9": {
      "type": "Text",
      "props": {
        "text": "9. Cool: Let the cookies cool on the baking sheet for a few minutes before transferring them to a wire rack to cool completely."
      },
      "children": []
    },
    "divider_2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "baking_tips_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "baking_tips_title",
        "baking_tips_list"
      ]
    },
    "baking_tips_title": {
      "type": "Text",
      "props": {
        "text": "Baking Tips",
        "variant": "h3"
      },
      "children": []
    },
    "baking_tips_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "tip_1",
        "tip_2",
        "tip_3"
      ]
    },
    "tip_1": {
      "type": "Text",
      "props": {
        "text": "• For perfectly uniform cookies, use a cookie scoop to portion the dough."
      },
      "children": []
    },
    "tip_2": {
      "type": "Text",
      "props": {
        "text": "• Don't overbake! The cookies will continue to bake on the hot pan after you remove them from the oven."
      },
      "children": []
    },
    "tip_3": {
      "type": "Text",
      "props": {
        "text": "• For a gourmet touch, sprinkle a little flaky sea salt on top of the cookies before baking."
      },
      "children": []
    }
  }
}
